const s = wb.getWorksheet('Sheet1');
const rows = s.getRange('A3:B21').getValues();
const targets = s.getRange('D5:D19').getValues().map(r => r[0]);
const pending = [...targets];
const kept = [];
for (const r of rows) {
  const i = pending.indexOf(r[0]);
  if (i >= 0) pending.splice(i, 1); else kept.push(r);
}
s.getRange('A3:B21').clear('contents');
s.getRange(`A3:B${2 + kept.length}`).setValues(kept);
log('unmatched targets', pending, 'kept', kept);
s.getRange('A1:K21')

